insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('CEL-301', 'A Product Person Running a Channel Business', 'Founder Psychology', 'internal', 'The founder can design and build the device, but getting it onto shelves, funding inventory and managing distributor margins are things nobody taught them. Those decisions get made on instinct.', 5, 9, '["Strong on product, weak on channel", "Distributor margins agreed on instinct", "Inventory funded without a plan", "Cannot say which channel actually pays"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["consumer_electronics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-301-1', (select problem_id from problems where problem_code = 'CEL-301'), 'Product Is the Comfort Zone', 'Psychological', 'The founder keeps improving the device because that is where they are confident, while the channel side is left to guesswork.', 0.74, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-301-2', (select problem_id from problems where problem_code = 'CEL-301'), 'Channel Economics Never Learned', 'Knowledge', 'Nobody taught the founder how distributor and retailer margins stack up, so the price they set does not survive the chain.', 0.72, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-301-3', (select problem_id from problems where problem_code = 'CEL-301'), 'Gap Not Named', 'Behavioural', 'The founder has not written down what they cannot do, so it is never tackled deliberately.', 0.66, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-CEL-301-1', (select problem_id from problems where problem_code = 'CEL-301'), '["RC-CEL-301-1", "RC-CEL-301-2", "RC-CEL-301-3"]'::jsonb, 'Founder Leverage', 'Consumer Electronics — Founder Skill Fit', '[]'::jsonb, '["Write out what your price becomes after every hand in the chain takes its cut.", "Work out what you actually keep per unit at the end of it.", "Price your next batch from that number, not from your cost."]'::jsonb, '[3, 4, 5]'::jsonb, '["consumer_electronics"]'::jsonb, '["Your price is not what the customer pays; it is what is left after the chain.", "One number, worked out properly, beats a spreadsheet you do not trust."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-CEL-301-2', (select problem_id from problems where problem_code = 'CEL-301'), '["RC-CEL-301-1", "RC-CEL-301-2", "RC-CEL-301-3"]'::jsonb, 'Founder Leverage', 'Consumer Electronics — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has sold through this channel before.", "Do it yourself ten times before handing it over."]'::jsonb, '[3, 4, 5]'::jsonb, '["consumer_electronics"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
