insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('CEL-302', 'All the Time Goes Into the Next Version of the Product', 'Founder Psychology', 'internal', 'The founder spends their weeks improving the device while orders, service complaints and dealer calls wait. Product work always feels like progress, so it always wins.', 5, 9, '["Weeks spent on product iterations", "Dealer and service work waits", "No planned time for sales", "Next version always in progress"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["consumer_electronics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-302-1', (select problem_id from problems where problem_code = 'CEL-302'), 'Product Work Always Wins', 'Behavioural', 'There is always something to improve, so the commercial work never gets a turn.', 0.74, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-302-2', (select problem_id from problems where problem_code = 'CEL-302'), 'No Time Reserved for Selling', 'Operational', 'No hours are set aside for dealers, service or numbers, so those happen only when something breaks.', 0.71, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-302-3', (select problem_id from problems where problem_code = 'CEL-302'), 'Building Feels Like Progress', 'Psychological', 'A week of product work feels productive and hides that no more units were sold.', 0.67, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-CEL-302-1', (select problem_id from problems where problem_code = 'CEL-302'), '["RC-CEL-302-1", "RC-CEL-302-2", "RC-CEL-302-3"]'::jsonb, 'Founder Leverage', 'Consumer Electronics — Founder Time Use', '[]'::jsonb, '["Block two half-days a week for dealers, service and numbers.", "Decide what they are for before the week starts.", "Check at month end what they produced in orders."]'::jsonb, '[3, 4, 5]'::jsonb, '["consumer_electronics"]'::jsonb, '["The next version does not sell the current one.", "Book the time or product work will take it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-CEL-302-2', (select problem_id from problems where problem_code = 'CEL-302'), '["RC-CEL-302-1", "RC-CEL-302-2", "RC-CEL-302-3"]'::jsonb, 'Founder Leverage', 'Consumer Electronics — Founder Time Use', '[]'::jsonb, '["Write what you did hour by hour for a week.", "Mark the hours only you could do.", "Give one product task to someone else."]'::jsonb, '[3, 4, 5]'::jsonb, '["consumer_electronics"]'::jsonb, '["You cannot fix your time until you can see it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
