insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('CEL-303', 'Dealers and Distributors Only Deal With the Founder', 'Founder Psychology', 'internal', 'Every dealer conversation, price negotiation and complaint comes to the founder. Nobody else has met them, so nothing moves when the founder is unavailable.', 5, 9, '["Founder is the only dealer contact", "Nobody else has met the distributor", "Negotiations wait for the founder", "Dealer terms unwritten"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["consumer_electronics"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-303-1', (select problem_id from problems where problem_code = 'CEL-303'), 'Single Contact by Default', 'Operational', 'Every dealer relationship started with the founder and was never widened, so there is no second contact.', 0.75, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-303-2', (select problem_id from problems where problem_code = 'CEL-303'), 'Terms Held in Memory', 'Knowledge', 'What was agreed with each dealer lives in the founder''s head and phone rather than in a record anyone can use.', 0.71, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-CEL-303-3', (select problem_id from problems where problem_code = 'CEL-303'), 'Relationships Guarded', 'Psychological', 'The founder believes dealers will only take them seriously, so the relationships are held rather than shared.', 0.67, 'internal', 'Stage 0→1', '["consumer_electronics"]'::jsonb) on conflict (root_cause_code) do nothing;
