insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ECM-301', 'Good at the Brand, Guessing at the Numbers', 'Founder Psychology', 'internal', 'The founder has taste and can build a brand people like, but reading what an ad actually earns, and whether a customer comes back, are things they have never learned. Spend decisions are made on feel.', 5, 9, '["Strong on brand, weak on numbers", "Ad spend judged on feel", "Repeat purchase not measured", "Cannot say which spend paid back"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["ecommerce_d2c"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-301-1', (select problem_id from problems where problem_code = 'ECM-301'), 'Numbers Never Learned', 'Knowledge', 'Nobody taught the founder how to read what a channel earns after returns and shipping, so spend is judged on the top line.', 0.75, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-301-2', (select problem_id from problems where problem_code = 'ECM-301'), 'Brand Is the Comfort Zone', 'Psychological', 'Creative and brand work feel productive and familiar, so the numbers keep being postponed.', 0.71, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-301-3', (select problem_id from problems where problem_code = 'ECM-301'), 'Gap Not Named', 'Behavioural', 'The founder has not written down what they cannot do, so nothing is done about it deliberately.', 0.66, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-301-1', (select problem_id from problems where problem_code = 'ECM-301'), '["RC-ECM-301-1", "RC-ECM-301-2", "RC-ECM-301-3"]'::jsonb, 'Founder Leverage', 'E-Commerce & D2C — Founder Skill Fit', '[]'::jsonb, '["Work out what one order actually leaves you after product, shipping and returns.", "Do it separately for each channel you sell on.", "Make your next spend decision from those two numbers."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["Revenue is not the number; what is left after returns and shipping is.", "One number per channel beats a dashboard you do not trust."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-301-2', (select problem_id from problems where problem_code = 'ECM-301'), '["RC-ECM-301-1", "RC-ECM-301-2", "RC-ECM-301-3"]'::jsonb, 'Founder Leverage', 'E-Commerce & D2C — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has run paid spend properly.", "Do it yourself for a month before handing it over."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
