insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ECM-302', 'The Day Goes on Order Problems and Customer Messages', 'Founder Psychology', 'internal', 'Wrong deliveries, return requests and customer messages fill the founder''s day. The work that would reduce those problems, and the work of growing, never gets time.', 5, 9, '["Day spent on order problems", "Answering customer messages personally", "No time for growth work", "Same problems every week"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["ecommerce_d2c"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-302-1', (select problem_id from problems where problem_code = 'ECM-302'), 'Symptoms Handled, Causes Left', 'Behavioural', 'Each problem is solved for the customer and the reason it happened is never worked on, so it returns.', 0.74, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-302-2', (select problem_id from problems where problem_code = 'ECM-302'), 'No Time Reserved', 'Operational', 'No hours are set aside for fixing causes or planning, so only today''s problems get attention.', 0.71, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-302-3', (select problem_id from problems where problem_code = 'ECM-302'), 'Answering Feels Like Service', 'Psychological', 'Replying to every customer personally feels like good service and hides that the service keeps failing.', 0.67, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-302-1', (select problem_id from problems where problem_code = 'ECM-302'), '["RC-ECM-302-1", "RC-ECM-302-2", "RC-ECM-302-3"]'::jsonb, 'Founder Leverage', 'E-Commerce & D2C — Founder Time Use', '[]'::jsonb, '["Write down every customer problem for one week and group them.", "Spend one protected half-day fixing the cause of the biggest group.", "Count that group again next week."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["Fix the biggest group''s cause, not the loudest single message.", "Count before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-302-2', (select problem_id from problems where problem_code = 'ECM-302'), '["RC-ECM-302-1", "RC-ECM-302-2", "RC-ECM-302-3"]'::jsonb, 'Founder Leverage', 'E-Commerce & D2C — Founder Time Use', '[]'::jsonb, '["List where your hours went last week.", "Mark the hours only you could do.", "Hand one problem type to someone else with the steps written."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["A recurring problem is a process gap, not a founder task."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
