insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ECM-303', 'Nothing Goes Out Without the Founder Approving It', 'Founder Psychology', 'internal', 'Every photo, every caption and every discount waits for the founder''s approval. Testing moves at the speed of one person''s attention, and their taste has never been written down as rules.', 5, 9, '["Founder approves every creative", "Discounts wait for approval", "Testing limited by one person", "Brand rules unwritten"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["ecommerce_d2c"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-303-1', (select problem_id from problems where problem_code = 'ECM-303'), 'Taste Never Written as Rules', 'Knowledge', 'The founder''s judgement about the brand was never written down, so every decision has to pass through them.', 0.75, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
