insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ECM-306', 'Hired for Enthusiasm, Not for the Skill the Role Needs', 'Team & Leadership', 'internal', 'People are hired quickly when orders grow, chosen on energy rather than on whether they can do the specific work. Nobody can say afterwards whether they are performing.', 5, 9, '["Hired fast on enthusiasm", "Specific skill not tested", "No written expectations", "Cannot say if someone is performing"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["ecommerce_d2c"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-306-1', (select problem_id from problems where problem_code = 'ECM-306'), 'Skill Not Tested', 'Operational', 'Hiring checks attitude but never the actual skill the role needs, which is discovered on the job.', 0.74, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-306-2', (select problem_id from problems where problem_code = 'ECM-306'), 'Role Not Described', 'Operational', 'The need is more hands, not a role, so nothing is written to measure against.', 0.70, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-306-3', (select problem_id from problems where problem_code = 'ECM-306'), 'No Definition of Good', 'Knowledge', 'Nobody wrote what a good week looks like, so performance is a matter of impression.', 0.67, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
