insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ECM-309', 'What You Tried and What Happened Is Not Written Down', 'Strategy & Planning', 'internal', 'Ads, offers and product tests are run and forgotten. With no record, the same tests get run again and settled questions get re-argued.', 5, 9, '["Test results not recorded", "Same tests repeated", "No record of what was learned", "Decisions re-argued without evidence"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["ecommerce_d2c"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-309-1', (select problem_id from problems where problem_code = 'ECM-309'), 'No Test Record', 'Operational', 'Tests run inside the ad platform and are never written up, so the learning disappears when the campaign is archived.', 0.76, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-309-2', (select problem_id from problems where problem_code = 'ECM-309'), 'Learning Not Separated From Reporting', 'Knowledge', 'Reports show what spend did, not what was learned, so nothing accumulates into a view.', 0.71, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ECM-309-3', (select problem_id from problems where problem_code = 'ECM-309'), 'Turnover Resets Everything', 'Behavioural', 'Each new marketer or agency starts from scratch because there is no record of what has been tried.', 0.68, 'internal', 'Stage 0→1', '["ecommerce_d2c"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-309-1', (select problem_id from problems where problem_code = 'ECM-309'), '["RC-ECM-309-1", "RC-ECM-309-2", "RC-ECM-309-3"]'::jsonb, 'Strategic Focus', 'E-Commerce & D2C — What Gets Remembered', '[]'::jsonb, '["Keep a one-line log: what you tried, what happened, what you concluded.", "Check the log before briefing a new test.", "Write one page a quarter on what you now believe and why."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["A test with no written conclusion was an expense, not an experiment.", "The log is what makes an agency handover cheap."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-ECM-309-2', (select problem_id from problems where problem_code = 'ECM-309'), '["RC-ECM-309-1", "RC-ECM-309-2", "RC-ECM-309-3"]'::jsonb, 'Strategic Focus', 'E-Commerce & D2C — What Gets Remembered', '[]'::jsonb, '["Make any new marketer or agency read the log first.", "Record why you stopped a channel, not just that you did.", "Read the log before each quarter''s plan."]'::jsonb, '[3, 4, 5]'::jsonb, '["ecommerce_d2c"]'::jsonb, '["Write down why you stopped, or you will start again."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
