insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('EDU-301', 'A Teacher Running a Business They Were Never Taught', 'Founder Psychology', 'internal', 'The founder can teach brilliantly, but pricing courses, collecting fees and reading whether the business makes money are things nobody taught them. So they keep teaching, where they know they are good.', 5, 9, '["Excellent teaching, unsure about the business", "Fees priced by guesswork", "Avoids collection conversations", "Cannot say if a batch made money"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["edtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-301-1', (select problem_id from problems where problem_code = 'EDU-301'), 'Teaching Is the Comfort Zone', 'Psychological', 'The classroom is where the founder feels skilled, so that is where the day goes while the business side is left alone.', 0.74, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-301-2', (select problem_id from problems where problem_code = 'EDU-301'), 'Business Side Never Learned', 'Knowledge', 'Nobody taught the founder how to price a course or work out what a batch earns, so those are guesses.', 0.71, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-301-3', (select problem_id from problems where problem_code = 'EDU-301'), 'Gap Not Named', 'Behavioural', 'The founder has not written down what they cannot do, so it never gets addressed on purpose.', 0.66, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-EDU-301-1', (select problem_id from problems where problem_code = 'EDU-301'), '["RC-EDU-301-1", "RC-EDU-301-2", "RC-EDU-301-3"]'::jsonb, 'Founder Leverage', 'Education & EdTech — Founder Skill Fit', '[]'::jsonb, '["Work out what one batch actually earns after teacher cost, space and materials.", "Do it for your last three batches.", "Price the next one from that number."]'::jsonb, '[3, 4, 5]'::jsonb, '["edtech"]'::jsonb, '["A full batch and a profitable batch are not the same thing.", "Start with one number you can defend."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
