insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('EDU-302', 'The Founder Teaches Every Class, So Nobody Runs the Institute', 'Founder Psychology', 'internal', 'The founder''s own teaching hours are the main income, so there are no hours left to run the business. Stepping out of the classroom feels like losing students.', 5, 9, '["Founder teaches most classes", "No hours for running the institute", "Admin done after classes", "No planned time for growth"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["edtech"]'::jsonb) on conflict (problem_code) do nothing;
