insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-302-2', (select problem_id from problems where problem_code = 'EDU-302'), 'Nothing Protected in the Timetable', 'Behavioural', 'No hours are blocked, so classes fill everything and business work goes to the end of the day.', 0.71, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
