insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('EDU-303', 'Students and Parents Enrol Because of the Founder', 'Founder Psychology', 'internal', 'Parents enrol because of the founder''s reputation and want their child in the founder''s class. The institute''s income depends on one person''s presence, and handing a batch over risks losing families.', 5, 9, '["Parents ask for the founder''s class", "Enrolment tied to the founder''s name", "Handing over risks losing families", "No teacher trained to the same standard"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["edtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-303-1', (select problem_id from problems where problem_code = 'EDU-303'), 'Reputation Attached to a Person', 'Behavioural', 'Families were won by the founder personally and never introduced to anyone else, so trust sits with a person.', 0.75, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-303-2', (select problem_id from problems where problem_code = 'EDU-303'), 'No Teacher Trained to the Standard', 'Knowledge', 'No other teacher has been trained to the founder''s approach, so handing over genuinely does risk the result.', 0.71, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-303-3', (select problem_id from problems where problem_code = 'EDU-303'), 'Handover Never Attempted', 'Psychological', 'The founder fears losing families more than being the bottleneck, so it is never tried.', 0.67, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-EDU-303-1', (select problem_id from problems where problem_code = 'EDU-303'), '["RC-EDU-303-1", "RC-EDU-303-2", "RC-EDU-303-3"]'::jsonb, 'Founder Leverage', 'Education & EdTech — Founder Dependency', '[]'::jsonb, '["Pick one batch and co-teach it with another teacher for three weeks.", "Let them take the fourth week while you are in the building.", "Ask the parents afterwards how it went."]'::jsonb, '[3, 4, 5]'::jsonb, '["edtech"]'::jsonb, '["Hand over by teaching together, not by announcing a change.", "The test is whether families re-enrol with them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-EDU-303-2', (select problem_id from problems where problem_code = 'EDU-303'), '["RC-EDU-303-1", "RC-EDU-303-2", "RC-EDU-303-3"]'::jsonb, 'Founder Leverage', 'Education & EdTech — Founder Dependency', '[]'::jsonb, '["Write your teaching approach for one course, session by session.", "Train one teacher to it and sit in on three of their sessions.", "Put the plan where teachers can use it."]'::jsonb, '[3, 4, 5]'::jsonb, '["edtech"]'::jsonb, '["You cannot hand over an approach you have never written down."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
