insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('EDU-304', 'Nobody Owns Whether Students Actually Finish', 'Team & Leadership', 'internal', 'Admissions, attendance follow-up and results are handled by whoever is free. When students drop out, there is no one whose job it was to notice.', 5, 9, '["Admissions and follow-up done by whoever is free", "No owner for drop-outs", "Attendance not followed up", "Drop-outs noticed too late"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["edtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-304-1', (select problem_id from problems where problem_code = 'EDU-304'), 'No Owner for Completion', 'Operational', 'Nobody was made responsible for whether students finish, so drop-outs are noticed only at the end.', 0.76, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-304-2', (select problem_id from problems where problem_code = 'EDU-304'), 'Duties Not Written', 'Operational', 'Admissions, follow-up and results were never assigned in writing, so they overlap and leave gaps.', 0.71, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-304-3', (select problem_id from problems where problem_code = 'EDU-304'), 'Found Late, Not Predicted', 'Behavioural', 'Attendance is not watched week by week, so a student is gone before anyone acts.', 0.68, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-EDU-304-1', (select problem_id from problems where problem_code = 'EDU-304'), '["RC-EDU-304-1", "RC-EDU-304-2", "RC-EDU-304-3"]'::jsonb, 'Team Effectiveness', 'Education & EdTech — Role Clarity', '[]'::jsonb, '["Name one person responsible for students finishing.", "Have them check attendance weekly and call anyone who missed twice.", "Ask that person, not the team, when someone drops out."]'::jsonb, '[3, 4, 5]'::jsonb, '["edtech"]'::jsonb, '["Someone has to own whether students finish, or nobody does.", "Two missed sessions is the signal; act on it that week."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-EDU-304-2', (select problem_id from problems where problem_code = 'EDU-304'), '["RC-EDU-304-1", "RC-EDU-304-2", "RC-EDU-304-3"]'::jsonb, 'Team Effectiveness', 'Education & EdTech — Role Clarity', '[]'::jsonb, '["Write who owns admissions, follow-up and results.", "Keep one list of at-risk students with an owner.", "Review it weekly."]'::jsonb, '[3, 4, 5]'::jsonb, '["edtech"]'::jsonb, '["A weekly list makes drop-out preventable rather than reportable."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
