insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('EDU-305', 'Only the Founder Can Agree a Fee Concession', 'Team & Leadership', 'internal', 'Staff cannot agree a discount, a payment plan or a refund. Parents negotiate with the founder directly, and admissions stall while they wait.', 5, 9, '["Staff cannot agree concessions", "Parents wait for the founder", "No written limits", "Admissions stall on approvals"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["edtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-305-1', (select problem_id from problems where problem_code = 'EDU-305'), 'No Limit Given', 'Operational', 'Nobody has a concession they can agree, so every negotiation reaches the founder.', 0.75, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-305-2', (select problem_id from problems where problem_code = 'EDU-305'), 'Fear of Giving Too Much', 'Psychological', 'The founder expects staff to give away too much, so no limit is set.', 0.70, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
