insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-308-2', (select problem_id from problems where problem_code = 'EDU-308'), 'No Test for a New Course', 'Operational', 'There is no rule a new course must pass, so every request becomes one.', 0.71, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-EDU-308-3', (select problem_id from problems where problem_code = 'EDU-308'), 'Enrolment per Course Not Watched', 'Knowledge', 'Nobody looks at enrolment and completion per course, so weak ones stay on the list.', 0.68, 'internal', 'Stage 0→1', '["edtech"]'::jsonb) on conflict (root_cause_code) do nothing;
