insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ENR-302', 'Every Site Visit and Installation Needs the Founder There', 'Founder Psychology', 'internal', 'The founder attends every survey, installation and commissioning. The days are full and the work of winning the next project never gets time.', 5, 9, '["Founder attends every site", "No time for the next project", "Paperwork done at night", "Same site issues repeat"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["cleantech_energy"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-302-1', (select problem_id from problems where problem_code = 'ENR-302'), 'Site Work Always Urgent', 'Behavioural', 'Every installation needs the founder today, so selling and planning never get a turn.', 0.74, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-302-2', (select problem_id from problems where problem_code = 'ENR-302'), 'No Time Reserved', 'Operational', 'No hours are set aside for the pipeline or the numbers, so those happen after hours.', 0.71, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-302-3', (select problem_id from problems where problem_code = 'ENR-302'), 'Presence Read as Quality Control', 'Psychological', 'Being on site feels like the only way to keep standards, and it is never tested.', 0.67, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
