insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ENR-304', 'Nobody Owns Whether the System Actually Performs After Handover', 'Team & Leadership', 'internal', 'Once a system is installed, monitoring output, handling underperformance and servicing are done by whoever is free. Customers discover problems before anyone here does.', 5, 9, '["No owner after handover", "Performance not monitored", "Underperformance found by the customer", "Servicing done ad hoc"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["cleantech_energy"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-304-1', (select problem_id from problems where problem_code = 'ENR-304'), 'No Owner After Handover', 'Operational', 'Nobody is responsible for the system once it is commissioned, so performance is only checked when a customer complains.', 0.76, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-304-2', (select problem_id from problems where problem_code = 'ENR-304'), 'Output Not Monitored', 'Operational', 'There is no routine check of what an installed system is actually producing, so underperformance goes unnoticed.', 0.72, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-304-3', (select problem_id from problems where problem_code = 'ENR-304'), 'Duties Not Written', 'Behavioural', 'Monitoring and servicing were never assigned in writing, so they fall between people.', 0.68, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
