insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-308-1', (select problem_id from problems where problem_code = 'ENR-308'), 'Nothing Refused', 'Strategic', 'Every segment and scheme is pursued because refusing feels like losing, so effort is never concentrated.', 0.76, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-308-2', (select problem_id from problems where problem_code = 'ENR-308'), 'No Test for Taking Work', 'Operational', 'There is no rule an opportunity must pass, so each is judged alone and all sound reasonable.', 0.71, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-308-3', (select problem_id from problems where problem_code = 'ENR-308'), 'Cost to Pursue Not Measured', 'Knowledge', 'Nobody measures what chasing a scheme or segment actually costs in time, so the unprofitable ones stay.', 0.68, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
