insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('ENR-309', 'Site Conditions and Performance Data Are Not Recorded', 'Strategy & Planning', 'internal', 'What made a site difficult, what the actual output turned out to be, which supplier''s component failed — none of it is written down. Every quote and every install starts from nothing.', 5, 9, '["Site conditions not recorded", "Actual output not compared to the quote", "Component failures not tracked", "Same estimating mistakes repeat"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["cleantech_energy"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-309-1', (select problem_id from problems where problem_code = 'ENR-309'), 'No Site Record', 'Operational', 'What made a site hard, and what it finally produced, is not recorded, so estimating never improves.', 0.76, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-309-2', (select problem_id from problems where problem_code = 'ENR-309'), 'Quoted Versus Actual Never Compared', 'Knowledge', 'Nobody compares what was promised with what the system delivered, so the estimating error stays invisible.', 0.72, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-ENR-309-3', (select problem_id from problems where problem_code = 'ENR-309'), 'Component Failures Not Tracked', 'Behavioural', 'Failures are replaced and not recorded against the supplier or batch, so patterns never appear.', 0.68, 'internal', 'Stage 0→1', '["cleantech_energy"]'::jsonb) on conflict (root_cause_code) do nothing;
