insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('MED-301', 'A Creative Person Running a Business They Never Studied', 'Founder Psychology', 'internal', 'The founder can make the work, but quoting a project, negotiating rights and chasing payment are things nobody taught them. So they keep making, where they are strong.', 5, 9, '["Strong creatively, weak commercially", "Projects quoted on instinct", "Avoids payment conversations", "Cannot say which projects made money"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["media_entertainment"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-301-1', (select problem_id from problems where problem_code = 'MED-301'), 'Making Is the Comfort Zone', 'Psychological', 'The founder returns to the creative work because that is where they are confident, while the commercial side stays guesswork.', 0.74, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-301-2', (select problem_id from problems where problem_code = 'MED-301'), 'Quoting Never Learned', 'Knowledge', 'Nobody taught the founder how to quote for time, revisions and rights, so quotes do not survive the project.', 0.72, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-301-3', (select problem_id from problems where problem_code = 'MED-301'), 'Project Outcome Never Checked', 'Behavioural', 'Projects are delivered and moved on from without working out what each actually earned.', 0.67, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
