insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-304-1', (select problem_id from problems where problem_code = 'MED-304'), 'No Owner for Scope', 'Operational', 'Nobody is responsible for what is in and out of a project, so requests are accepted by whoever hears them.', 0.76, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-304-2', (select problem_id from problems where problem_code = 'MED-304'), 'Revisions Not Counted', 'Knowledge', 'Nobody counts revisions against what was quoted, so scope creep is invisible until the project is late.', 0.72, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-MED-304-3', (select problem_id from problems where problem_code = 'MED-304'), 'Saying No Feels Risky', 'Psychological', 'Refusing a client request feels like risking the relationship, so scope grows quietly.', 0.68, 'internal', 'Stage 0→1', '["media_entertainment"]'::jsonb) on conflict (root_cause_code) do nothing;
