insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-MED-304-2', (select problem_id from problems where problem_code = 'MED-304'), '["RC-MED-304-1", "RC-MED-304-2", "RC-MED-304-3"]'::jsonb, 'Team Effectiveness', 'Entertainment & Media — Role Clarity', '[]'::jsonb, '["Write what is in and out of scope in every quote.", "Review revisions against the quote at project close.", "Price extra revisions rather than absorbing them."]'::jsonb, '[3, 4, 5]'::jsonb, '["media_entertainment"]'::jsonb, '["Scope written into the quote is easier to defend than scope explained later."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
